triple A = (4,8,0);
triple B= (4,0,0);
triple C = (0,0,0);
triple D = (0,8,0);
triple P = (4,8,6);
draw(B--P--D--A--B);
draw(A--P);
draw(A--C--P, dashed);
draw(B--C--D,dashed);
label("$A$",A,S);
label("$B$",B,W);
label("$C$",C,S);
label("$D$",D,E);
label("$P$",P,N);
